from collections import defaultdict


def is_valid(xs):
    d = defaultdict(lambda: 0)
    for x in xs:
        d[x] += 1

    if len(xs) % 2 == 0:
        for v in range(1, len(xs), 2):
            if d[v] != 2:
                return False
    else:
        if d[0] != 1:
            return False
        for v in range(2, len(xs), 2):
            if d[v] != 2:
                return False

    return True


