    assert np.sum(adj_mat) == M * 2

    next_nodes = np.argwhere(adj_mat[0].flatten() == 1)
    n_paths = np.sum([visit(next_node, [0, ], adj_mat)
                      for next_node in next_nodes])

    print(n_paths)


