import itertools

def solve(cs):#初項>0
    ans = 0
    diff = 0
    for i in range(len(cs)):
        if i%2 == 1:
            if cs[i]+diff < 0:
                continue
            ans += abs(cs[i]+diff)+1
            diff += -abs(cs[i]+diff)-1
        else:
            if (cs[i]+diff) > 0:
                continue
            ans += abs(cs[i]+diff)+1
            diff += abs(cs[i]+diff)+1

    return ans

def solvem(cs):
    ans = 0
    diff = 0
    for i in range(len(cs)):
        if i%2 == 1:
            if cs[i]+diff > 0:
                continue
            ans += abs(cs[i]+diff)+1
            diff += abs(cs[i]+diff)+1
        else:
            if (cs[i]+diff) < 0:
                continue
            ans += abs(cs[i]+diff)+1
            diff += -abs(cs[i]+diff)-1

    return ans

