def min_max_colors(nums):
    thresholds = {400:0, 800:0, 1200:0, 1600:0, 2000:0, 2400:0, 2800:0, 3200:0}

    mi, ma = 0, 0

    for num in nums:
        if num >= 3200:
            ma += 1
        else:
            for th in sorted(thresholds.keys()):
                if num < th:
                    thresholds[th] += 1
                    break

    different_colors = sum(1 if thresholds[th] > 0 else 0 for th in thresholds)
    mi, ma = mi + different_colors, ma + different_colors

    return max(1, mi), ma


