def slv(S):
    S = [c for c in S]
    l = []
    r = []
    la = []
    for c in S:
        if c == ')':
            if l:
                l.pop()
            else:
                la.append('(')
        else:
            l.append('(')
    S = la + S + [')' for _ in range(len(l))]
    return ''.join(S)


