def solve():
    [N, M] = [int(x) for x in input().split()]

    M, N = max(N, M), min(N, M)

    if abs(N - M) > 1:
        return 0

    Nfact = 1
    MOD = 10**9 + 7

    for i in range(1, N+1):
        Nfact = Nfact * i % MOD

    Nfact2 = Nfact * Nfact % MOD

    if N == M:
        return Nfact2 * 2 % MOD
    else:
        return (N+1) * Nfact2 % MOD


