class SegmentTree:
    """
    演算子は要素とセットでモノイドを形成するようなものでなければならない。
    すなわち、結合律が成り立ち単位元が存在する必要がある。(ただし単位元は添加可能)
    """

    @classmethod
    def all_identity(cls, operator, identity, size):
        return cls(operator, identity, [identity] * (2 << (size - 1).bit_length()))

    @classmethod
    def from_initial_data(cls, operator, identity, data):
        size = 1 << (len(data) - 1).bit_length()
        temp = [identity] * (2 * size)
        temp[size:size + len(data)] = data
        data = temp

        for i in reversed(range(size)):
            data[i] = operator(data[2 * i], data[2 * i + 1])
        return cls(operator, identity, data)

    # これ使わずファクトリーメソッド使いましょうね
    def __init__(self, operator, identity, data):
        self.op = operator
        self.id = identity
        self.data = data
        self.size = len(data) // 2

    def _interval(self, a, b):
        a += self.size
        b += self.size
        ra = self.id
        rb = self.id

        data = self.data
        op = self.op
        while a < b:
            if a & 1:
                ra = op(ra, data[a])
                a += 1
            if b & 1:
                b -= 1
                rb = op(data[b], rb)
            a >>= 1
            b >>= 1
        return op(ra, rb)

    def __getitem__(self, i):
        if isinstance(i, slice):
            return self._interval(
                0 if i.start is None else i.start,
                self.size if i.stop is None else i.stop)
        elif isinstance(i, int):
            return self.data[i + self.size]

    def __setitem__(self, i, v):
        i += self.size
        data = self.data
        op = self.op
        while i:
            data[i] = v
            v = op(data[i ^ 1], v) if i & 1 else op(v, data[i ^ 1])
            i >>= 1

    def __iter__(self):
        return iter(self.data[self.size:])


class LazySegmentTree:
    """
    op: 区間取得クエリでreduceする際に使う演算子
    apply: 更新則の適用
    comp: 更新則の合成

    range_query: reduce(op, (apply(x,m) for x,m in zip(X,M)))

    満たすべき性質:

    集合X (要素)
    op[+]: X,X -> X
    (X, op)はモノイド

    集合M (更新則)
    comp[*]: M,M -> M
    (M, compose)はモノイド

    apply[f(x,m,n)]: X,M,Z+ -> X
    (Z+は区間長)

    f(x,e_M,n) = x
    f(x,m*n,p) = f(f(x,m,p),n,p)
    f(x,m,p)+f(y,m,q) = f(x+y,m,p+q)

    参考: https://algo-logic.info/segment-tree/#toc_id_3
    """

    @classmethod
    def all_identity(cls, op, op_e, comp, comp_e, apply, size):
        size = 1 << (size - 1).bit_length()
        return cls(
            op,
            op_e,
            comp,
            comp_e,
            apply,
            [op_e] * (2 * size),
            [comp_e] * size
        )

    @classmethod
    def from_initial_data(cls, op, op_e, comp, comp_e, apply, data):
        size = 1 << (len(data) - 1).bit_length()
        temp = [op_e] * (2 * size)
        temp[size:size + len(data)] = data

        for i in reversed(range(size)):
            temp[i] = op(temp[2 * i], temp[2 * i + 1])
        return cls(
            op,
            op_e,
            comp,
            comp_e,
            apply,
            temp,
            [comp_e] * size
        )

    # これ使わずファクトリーメソッド使いましょうね
    def __init__(self, op, op_e, comp, comp_e, apply, data, lazy):
        self.op = op
        self.op_e = op_e
        self.comp = comp
        self.comp_e = comp_e
        self.apply = apply
        self.data = data
        self.lazy = lazy
        self.size = len(self.data) // 2
        self.depth = self.size.bit_length() - 1
        self._l_indices = [0] * self.depth
        self._r_indices = [0] * self.depth

    def _update_indices(self, i, l):
        m = i // (i & -i)
        i >>= 1
        for k in range(self.depth):
            l[k] = i if i < m else 0
            i >>= 1

    def _propagate_top_down(self):
        data = self.data
        lazy = self.lazy
        apply = self.apply
        comp = self.comp
        comp_e = self.comp_e
        k = self.size >> 1

        for i, j in zip(reversed(self._l_indices), reversed(self._r_indices)):
            if i > 0:
                temp = lazy[i]
                if temp != comp_e:
                    lazy[i] = comp_e
                    a = i << 1
                    b = a | 1
                    data[a] = apply(data[a], temp, k)
                    data[b] = apply(data[b], temp, k)
                    if k > 1:
                        lazy[a] = comp(lazy[a], temp)
                        lazy[b] = comp(lazy[b], temp)
            if i < j:
                temp = lazy[j]
                if temp != comp_e:
                    lazy[j] = comp_e
                    a = j << 1
                    b = a | 1
                    data[a] = apply(data[a], temp, k)
                    data[b] = apply(data[b], temp, k)
                    if k > 1:
                        lazy[a] = comp(lazy[a], temp)
                        lazy[b] = comp(lazy[b], temp)
            k >>= 1

    def _propagate_bottom_up(self):
        data = self.data
        op = self.op
        for i, j in zip(self._l_indices, self._r_indices):
            if i < j:
                data[j] = op(data[j << 1], data[j << 1 | 1])
            if i > 0:
