class BinaryIndexedTree:
    def __init__(self, size):
        self.data = [0] * (size + 1)
        self.msb = 1 << (size.bit_length() - 1)

    def _add(self, i, w):
        i += 1
        while i < len(self.data):
            self.data[i] += w
            i += i & -i

    def _get_sum(self, i):
        res = 0
        while i > 0:
            res += self.data[i]
            i -= i & -i
        return res

    def __getitem__(self, i):
        """
        [0,i)
        """
        if isinstance(i, slice):
            a = self._get_sum(len(self.data) - 1 if i.stop is None else i.stop)
            b = self._get_sum(0 if i.start is None else i.start)
            return a - b
        else:
            return 0  # fake value

    __setitem__ = _add

    def bisect_left(self, v):
        """
        return smallest i s.t v <= sum[:i+1]
        """
        i = 0
        k = self.msb
        l = len(self.data)
        while k > 0:
            i += k
            if i < l and self.data[i] < v:
                v -= self.data[i]
            else:
                i -= k
            k >>= 1
        return i

    def bisect_right(self, v):
        """
        return smallest i s.t v < sum[:i+1]
        """
        i = 0
        k = self.msb
        l = len(self.data)
        while k > 0:
            i += k
            if i < l and self.data[i] <= v:
                v -= self.data[i]
            else:
                i -= k
            k >>= 1
        return i

    bisect = bisect_right
