    @property
    def post_order(self):
        """
        bottom vertices first
        """
        return (~v for v in self.prepost_order if v < 0)

    @property
    def pre_order(self):
        """
        top vertices first
        """
        return (v for v in self.prepost_order if v >= 0)

    @property
    def prepost_order(self):
        """
        if v >= 0: it's pre-order entry
        otherwise: it's post-order entry
        """
        try:
            return self._prepost_order
        except AttributeError:
            order = [0] * (self.n_vertices * 2)
            stack = [~self.root, self.root]
            i = 0
            for i in range(self.n_vertices * 2):
                v = stack.pop()
                order[i] = v
                if v >= 0:
                    for u in self.children(v):
                        stack.append(~u)
                        stack.append(u)
