def scc(graph, rgraph):
    n = graph.n_vertices
    order = []
    color = [0] * n
    for v0 in range(n):
        if color[v0]:
            continue
        color[v0] = -1
        stack = [iter(graph.adj(v0))]
        path = [v0]
        while path:
            for u in stack[-1]:
                if color[u] == 0:
                    color[u] = -1
                    path.append(u)
                    stack.append(iter(graph.adj(u)))
                    break
            else:
                v = path.pop()
                order.append(v)
                stack.pop()

    label = 0
    for v0 in reversed(order):
        if color[v0] >= 0:
            continue
        color[v0] = label
        stack = [v0]
        while stack:
            v = stack.pop()
            for u in rgraph.adj(v):
                if color[u] < 0:
                    color[u] = label
                    stack.append(u)
        label += 1
    return label, color


def dijkstra(graph: BaseWeightedGraph, s: Union[int, Iterable[int]], t: Union[int, Iterable[int]] = -1,
             inf: Any = 2 ** 62) -> Tuple[List[int], Any]:
    """
    Returns a list of distance. If starts contains more than one vertex, returns the shortest distance from any of them.
    """
    K = graph.n_vertices.bit_length()
    MASK = (1 << K) - 1
    dist = [inf] * graph.n_vertices

    if isinstance(s, int):
        q = [s]
        dist[s] = 0
    else:
        q = list(s)
        for v in q:
            dist[v] = 0
    if isinstance(t, int):
        if t < 0:
            t = []
        else:
            t = [t]
    else:
        t = set(t)

    while q:
        x = hq.heappop(q)
        d, v = x >> K, x & MASK
        if v in t:
            return dist, d
        if d > dist[v]:
            continue
        for u, w in graph.wadj(v):
            if dist[u] > d + w:
                dist[u] = d + w
                hq.heappush(q, ((d + w) << K) | u)
    return dist, None


def dijkstra_general(graph: BaseWeightedGraph, inf: Any, zero: Any, s: Union[int, Iterable[int]],
                     t: Union[int, Iterable[int]] = -1) -> Tuple[List[Any], Any]:
    """
    Returns a list of distance. If starts contains more than one vertex, returns the shortest distance from any of them.
    """
    dist = [inf] * graph.n_vertices

    if isinstance(s, int):
        q = [(zero, s)]
        dist[s] = zero
    else:
        q = [(zero, v) for v in s]
        for d, v in q:
            dist[v] = zero
    if isinstance(t, int):
        if t < 0:
            t = []
        else:
            t = [t]
    else:
        t = set(t)

    while q:
        d, v = hq.heappop(q)
        if v in t:
            return dist, d
        if d > dist[v]:
            continue
        for u, w in graph.wadj(v):
            nw = d + w
            if dist[u] > nw:
                dist[u] = nw
                hq.heappush(q, (nw, u))
    return dist, None


