def general_bisect(ng: int, ok: int, judge: Callable[[int], V]) -> int:
    """
    一般化した二分法。一般の単調関数の根をO(log L)で見つける。

    :param ng: judge(ng)==Falseとなる値
    :param ok: judge(ok)==Trueとなる値
    :param judge: 真偽値を返す単調関数
    :return: judge(x)==Trueが成り立つギリギリの値
    """
    while abs(ng - ok) > 1:
        m = (ng + ok) // 2
        if judge(m):
            ok = m
        else:
            ng = m
    return ok


def fibonacci_search(left: int, right: int, func: Union[Callable[[int], V], Sequence], inf: V = 2 ** 60) -> Tuple[
    V, int]:
    """
    フィボナッチ探索法。極小値を一つだけ持つような関数の極小値をO(log L)で見つける。
    探索は(left, right)の範囲で行われる。

    :param left: 探索範囲の左端（含まない）
    :param right: 探索範囲の右端（含まない）
    :param func: 被最適化関数
    :param inf: funcの上界
    :return: (funcの極小値, 極小値を達成するfuncの引数)
    """
    try:
        func = func.__getitem__
    except AttributeError:
        pass
    f1, f2 = 1, 1
    while f1 + f2 < right - left:
        f1, f2 = f1 + f2, f1
    l = left
    m1 = func(l + f2)
    m2 = func(l + f1)
    while f1 > 2:
        f1, f2 = f2, f1 - f2
        if m1 > m2:
            l += f1
            m1 = m2
            m2 = func(l + f1) if l + f1 < right else inf
        else:
            m2 = m1
            m1 = func(l + f2)
    if m1 < m2:
        return m1, l + 1
    else:
        return m2, l + 2


