def zeta(data, merge):
    """
    （この関数はdataを上書きします）
    Mはモノイド
    data: 2^n -> M
    output: 2^n -> M
    merge: M -> M

    ouput[i] = sum(data[j] for j in range(2^n) if i|j == i)
    """
    n = len(data)
    while i < n:
        j = i
        while j < n:
            data[j] = merge(data[j], data[j & ~i])
            j = (j + 1) | i
        i <<= 1
    return data


def check_bipartiteness(n_vertices, edges):
    ds = DisjointSet(2 * n_vertices)

    for a, b in edges:
        ds.union(a, b + n_vertices)
        ds.union(b, a + n_vertices)

    next_color = 0
    color = [-1] * (2 * n_vertices)
    for v in range(n_vertices):
        ra = ds.find(v)
        rb = ds.find(v + n_vertices)
        if ra == rb:
            return None
        if color[ra] < 0:
            color[ra] = next_color
            color[rb] = next_color + 1
            next_color += 2
        color[v] = color[ra]
        color[v + n_vertices] = color[rb]
    return color[:n_vertices]


def small_range_duplicate(a):
    MASK = (1 << 32) - 1
    n = len(a)
    left = [i - 1 for i in range(n + 1)]
    right = [i + 1 for i in range(n + 1)]

    sorted_ind = sorted((~v << 32) | i for i, v in enumerate(a))
    t = 0
    vi = sorted_ind[t]
    i = vi & MASK
    v = ~(vi >> 32)
    while t < n:
        j = i
        l = left[i]
        pi = l
        pv = v
        while v == pv and left[i] == pi:
            pi = i
            t += 1
            if t >= n:
                break
            vi = sorted_ind[t]
            i = vi & MASK
            v = ~(vi >> 32)
        r = right[pi]
        right[l] = r
        while j <= pi:
            nj = right[j]
            left[j] = l
            right[j] = r
            j = nj
        left[r] = l

    return left, right


def small_range(a):
    N = len(a)
    MASK = (1 << 32) - 1
    left = [i - 1 for i in range(N + 1)]
    right = [i + 1 for i in range(N + 1)]
    sorted_ind = sorted((~v << 32) | i for i, v in enumerate(a))
    for v in sorted_ind:
        i = v & MASK
        left[right[-i]] = left[-i]
        right[left[-i]] = right[-i]

    return left, right


