class BinaryTrie:
    class Node:
        def __init__(self):
            self.zero = None
            self.one = None
            self.cnt = 0

    def __init__(self, bits):
        self.root = self.Node()
        self.bits = bits

    def add(self, v):
        n = self.root
        n.cnt += 1
        for d in reversed(range(self.bits)):
            if (v >> d) & 1:
                if not n.one:
                    n.one = self.Node()
                n = n.one
            else:
                if not n.zero:
                    n.zero = self.Node()
                n = n.zero
            n.cnt += 1

    def remove(self, v):
        n = self.root
        n.cnt -= 1
        for d in reversed(range(self.bits)):
            if (v >> d) & 1:
                n = n.one
            else:
                n = n.zero
            n.cnt -= 1

    def find_argminxor(self, v):
        n = self.root
        r = 0
        for d in reversed(range(self.bits)):
            if (v >> d) & 1:
                if n.one and n.one.cnt > 0:
                    n = n.one
                    r |= 1 << d
                else:
                    n = n.zero
            else:
                if n.zero and n.zero.cnt > 0:
                    n = n.zero
                else:
                    n = n.one
                    r |= 1 << d
        return r

    def __contains__(self, v):
        n = self.root
        for d in reversed(range(self.bits)):
            if (v >> d) & 1:
                n = n.one
            else:
                n = n.zero
            if not n or n.cnt == 0:
                return False
        return True
