        G[E[i][0]].add(E[i][1])

    def bfs(s):
        # find connected vertex by bfs
        vis_loc = [False] * N
        vis_loc[s] = True
        q = deque([s])
        while len(q):
            v = q.popleft()
            for n in G[v]:
                if vis_loc[n]:
                    continue
                q.append(n)
                vis_loc[n] = True
        return vis_loc
    vis = bfs(0)
    C = []
    for i in range(M):
        if vis[E[i][0]]:
