N = int(input())
S = []
for i in range(N):
    S.append(int(input()))

memo = {}


def solve(ind, points):
    # ending
    if ind == N:
        if points % 10 == 0:
            return 0
        else:
            return points

    if memo.get((ind, points)) is not None:
        return memo[(ind, points)]

    # transition
    ret = max(solve(ind=ind + 1, points=points + S[ind]), solve(ind=ind + 1, points=points))
    memo[(ind, points)] = ret

    return ret

