    list_item = [i for i in range(1, n)]
    list_pattern = []
    for i in range(2 ** (n - 1)):
        bag = []
        for j in range(n - 1):
            if ((i >> j) & 1):
                bag.append(list_item[j])

        bag.append(n)

        list_pattern.append(bag)

    return list_pattern

