from typing import TypeVar, overload, Type, Iterator, Tuple, Callable

T = TypeVar('T')
U = TypeVar('U')
@overload
def read_as(arg: Type[T], /, *, lines: int | None = None,
    perchar: bool = False, strip: bool = True) -> T: ...
@overload
def read_as(arg: Callable[..., T], /, *, lines: int | None = None,
    perchar: bool = False, strip: bool = True) -> T: ...
@overload
def read_as(arg1: Type[T], arg2: ellipsis, /, *, lines: int | None = None,
    perchar: bool = False, strip: bool = True) -> Iterator[T]: ...
@overload
def read_as(arg1: Type[T], arg2: Type[U], /, *, lines: int | None = None,
    perchar: bool = False, strip: bool = True) -> Tuple[T, U]: ...'''

from typing import Iterator, List
def read_as_adjlist(
        vertices: int, lines: int, decr: bool = False) -> List[List[int]]:
    from itertools import repeat
    push = list.append

    adjlist: List[List[int]] = [[] for _ in repeat(0, vertices)]
    it = read_as(Iterator[int], ..., lines=lines)
    if decr:
        for a, b in it:
            a -= 1; b -= 1
            push(adjlist[a], b)
            push(adjlist[b], a)
    else:
        for a, b in it:
            push(adjlist[a], b)
            push(adjlist[b], a)
    return adjlist


# ***** Main Code *****
def counting_roads():
    n, m = read_as(int, ...)

    paths = read_as_adjlist(n, lines=m, decr=True)
    return [*map(len, paths)]

